template<typename... Args>
void log_print(const Args&... args) {
    // C++17 Unary Left Fold Expression
    // Expands: (std::cout << arg1), (std::cout << arg2), ...
    ((std::cout << args << " "), ...);
    std::cout << std::endl;
}

// Pre-C++17 (Recursive Base Case)
void log_recursive() {}

template<typename T, typename... Rest>
void log_recursive(T head, Rest... tail) {
    std::cout << head << " ";
    log_recursive(tail...); // Recursion step
}
